import{_ as a,o as t,c as o,a6 as s}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Set up sounds and speech","description":"","frontmatter":{"title":"Set up sounds and speech","docId":"user.plugins.audio","translationKey":"user.plugins.audio","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b6be887705d13dfe120f3e07dc4006ec0efa1472b6dbe0ccfc1ebfc1e83f3672","translationRevision":"b6be887705d13dfe120f3e07dc4006ec0efa1472b6dbe0ccfc1ebfc1e83f3672","order":20},"headers":[],"relativePath":"en/user/plugins/audio.md","filePath":"en/user/plugins/audio.md","lastUpdated":1794591482000}'),n={name:"en/user/plugins/audio.md"};function i(r,e,d,c,l,u){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="set-up-sounds-and-speech" tabindex="-1">Set up sounds and speech <a class="header-anchor" href="#set-up-sounds-and-speech" aria-label="Permalink to &quot;Set up sounds and speech {#set-up-sounds-and-speech}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Play a predictable sound before connecting audio to busy LIVE activity. You need a working output device and an existing supported audio file. Local <strong>Play a sound</strong> (<code>audio.play</code>) is a built-in action; speech providers such as an installed SonicBoom integration require their own plugin/service configuration.</p><h2 id="test-a-local-sound" tabindex="-1">Test a local sound <a class="header-anchor" href="#test-a-local-sound" aria-label="Permalink to &quot;Test a local sound {#test-a-local-sound}&quot;">​</a></h2><ol><li>In <strong>Automations → Actions</strong>, create <strong>Play a sound</strong> (<code>audio.play</code>). Select an existing file with the media picker.</li><li>Set volume to <code>0.2</code> for a first check. The supported range is <code>0</code> to <code>1</code>; zero is silent.</li><li>Choose the overlap policy: <code>allow</code> permits concurrent playback, <code>restart</code> restarts the sound, and <code>drop</code> ignores a new instance while it is already playing.</li><li>Save the action and read the configuration before selecting <strong>Test</strong>. This test can play audible sound.</li><li>Listen through the intended device. After successful local playback, link the action to an event with a conservative <a href="./../automations/recipes.html">filter and cooldown</a>.</li></ol><p>The action retains a path-backed media reference. TikTools does not copy the audio file into its database. Keep the file at that path, and include it separately when moving or backing up your setup.</p><h2 id="configure-optional-speech" tabindex="-1">Configure optional speech <a class="header-anchor" href="#configure-optional-speech" aria-label="Permalink to &quot;Configure optional speech {#configure-optional-speech}&quot;">​</a></h2><p>Install the trusted speech plugin through <a href="./">Plugins</a>. In its connection/settings controls, verify the service address, authentication and selected provider, language and voice/profile. Load a voice catalog before testing a short non-sensitive sentence. A missing voice should be investigated as a catalog, ownership or provider mismatch rather than replaced with an invented identifier.</p><p>For SonicBoom, synthesis, playback admission and audible completion are different outcomes. A queued or started response does not prove a person heard the sentence. Cloned speech can be slower than chat arrival, so inspect queue/saturation diagnostics and keep event admission bounded.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Expected result, status and recovery <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Expected result, status and recovery {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Local audio playback is available when the host advertises audio support. Speech remains dependent on the installed plugin and reachable service; provider/device/platform acceptance is not guaranteed here. If silent, check file existence, volume, output device, pause state and the run error. If speech fails, check the service and voice catalog before retrying. Avoid repeated effect tests during a broadcast, and use <a href="./../preferences/troubleshooting.html">diagnostics</a> without sharing tokens or spoken private text.</p>',11)])])}const f=a(n,[["render",i]]);export{h as __pageData,f as default};
